use std::path::PathBuf;

/// Whether `id` is safe to use as one file or directory name: only
/// `[A-Za-z0-9._-]`, and not `.` or `..`. Ids generated by Terra Swarm
/// (`t-123`, `ws-4`) pass, while `../...`, separators and empty ids do not.
pub(crate) fn is_plain_path_component(id: &str) -> bool {
    !id.is_empty()
        && id != "."
        && id != ".."
        && id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
}

#[cfg(windows)]
pub fn home_dir() -> Option<PathBuf> {
    if let Ok(profile) = std::env::var("USERPROFILE") {
        if !profile.trim().is_empty() {
            return Some(PathBuf::from(profile));
        }
    }
    let (Ok(drive), Ok(path)) = (std::env::var("HOMEDRIVE"), std::env::var("HOMEPATH")) else {
        return None;
    };
    Some(PathBuf::from(format!("{}{}", drive, path)))
}

#[cfg(not(windows))]
pub fn home_dir() -> Option<PathBuf> {
    std::env::var("HOME").ok().map(PathBuf::from)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn given_terra_ids_when_checking_them_as_path_components_then_they_pass() {
        for id in ["t-123", "ws-4", "group_1.v2"] {
            assert!(is_plain_path_component(id), "{}", id);
        }
    }

    #[test]
    fn given_ids_that_could_leave_a_folder_when_checking_them_then_they_are_refused() {
        for id in ["", ".", "..", "../etc", "a/b", "a\\b", "t 1", "-ä"] {
            assert!(!is_plain_path_component(id), "{:?}", id);
        }
    }

    #[cfg(not(windows))]
    #[test]
    fn given_a_home_variable_when_looking_up_the_home_folder_then_it_is_returned() {
        let expected = std::env::var("HOME").ok().map(PathBuf::from);

        assert_eq!(home_dir(), expected);
    }
}
